mapper.select:
SELECT p.id, p.name, p.origin, p.roast_level, p.flavor_tags, p.process_method, p.cover_url, MIN(s.price) AS min_price FROM coffee_product p LEFT JOIN coffee_sku s ON p.id = s.product_id AND s.deleted = 0 WHERE p.deleted = 0 AND p.status = 1
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.origin LIKE CONCAT('%', #{keyword}, '%'))
AND p.roast_level = #{roastLevel}
AND p.flavor_tags LIKE CONCAT('%', #{flavorTag}, '%')
AND p.process_method = #{processMethod}
GROUP BY p.id ORDER BY p.create_time DESC
